const DOMAIN = 'apache.org';
const TAG = 'NGP-044';
const THRESHOLD_DAYS = 24;

const errors = [];
const rdap = $('Fetch RDAP').first().json || {};
const dns = $('Fetch NS Records').first().json || {};
const prevState = $('Get Previous State').first().json || {};
const prevAudit = $('Get Last Audit Hash').first().json || {};

// ---- Expiry from RDAP ----
let expiryDate = null;
let daysRemaining = null;
const ev = Array.isArray(rdap.events) ? rdap.events.find(e => e.eventAction === 'expiration') : null;
if (!ev || !ev.eventDate) {
  errors.push('RDAP expiration event missing');
} else {
  const exp = new Date(ev.eventDate);
  if (isNaN(exp.getTime())) {
    errors.push('RDAP expiration date unparseable');
  } else {
    const now = new Date();
    const expUTC = Date.UTC(exp.getUTCFullYear(), exp.getUTCMonth(), exp.getUTCDate());
    const nowUTC = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
    expiryDate = exp.toISOString();
    daysRemaining = Math.round((expUTC - nowUTC) / 86400000);
  }
}

// ---- Current NS from DNS-over-HTTPS ----
let currentNS = [];
if (dns.Status !== 0 || !Array.isArray(dns.Answer)) {
  errors.push('DNS NS lookup failed (status ' + dns.Status + ')');
} else {
  currentNS = [...new Set(
    dns.Answer.filter(a => a.type === 2)
      .map(a => String(a.data).toLowerCase().replace(/\.$/, ''))
  )].sort();
  if (currentNS.length === 0) errors.push('No NS records returned');
}

// ---- Previous state ----
let previousNS = null;
if (prevState.nameservers_json !== undefined && prevState.nameservers_json !== null) {
  previousNS = typeof prevState.nameservers_json === 'string'
    ? JSON.parse(prevState.nameservers_json)
    : prevState.nameservers_json;
  previousNS = [...previousNS].map(s => String(s).toLowerCase()).sort();
}
const firstRun = previousNS === null;
const monitoringError = errors.length > 0;
const nsChanged = !monitoringError && !firstRun &&
  JSON.stringify(previousNS) !== JSON.stringify(currentNS);
const expiryAlert = !monitoringError && daysRemaining < THRESHOLD_DAYS;
const alertRequired = expiryAlert || nsChanged;
const prevHash = prevAudit.input_sha256 || 'GENESIS';

// Canonical JSON: fixed key order, so the same evidence always hashes the same.
const canonical = JSON.stringify({
  tag: TAG, domain: DOMAIN, expiryDate, daysRemaining,
  currentNS, previousNS, nsChanged, alertRequired,
  monitoringError, errors, prevHash
});

const evidenceText = [
  'Domain: ' + DOMAIN,
  'Expiry date (RDAP): ' + expiryDate,
  'Days remaining: ' + daysRemaining,
  'Current nameservers: ' + JSON.stringify(currentNS),
  'Previous nameservers: ' + (firstRun ? 'none (first run baseline)' : JSON.stringify(previousNS)),
  'Nameservers changed: ' + nsChanged,
  'Expiry threshold: under ' + THRESHOLD_DAYS + ' days',
  'Program alert decision (authoritative): ' + (alertRequired ? 'ALERT' : 'NO ALERT'),
  'Monitoring errors: ' + (errors.length ? errors.join('; ') : 'none')
].join('\n');

return [{ json: {
  tag: TAG, domain: DOMAIN, expiryDate, daysRemaining, currentNS, previousNS,
  firstRun, nsChanged, expiryAlert, alertRequired, monitoringError, errors,
  prevHash, canonical, evidenceText
}}];

const d = $('Hash Input').first().json;
const agent = $input.first().json || {};
const raw = String(agent.output || '').trim();

const LEVELS = ['INFO', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];
// Deterministic fallback severity (used if the AI is down or returns junk)
let fallback = 'INFO';
if (d.monitoringError) fallback = 'HIGH';
else if (d.nsChanged) fallback = 'HIGH';
else if (d.daysRemaining < 7) fallback = 'CRITICAL';
else if (d.daysRemaining < 24) fallback = 'MEDIUM';

let severity = fallback;
let summary = '';
const m = raw.match(/^\s*(INFO|LOW|MEDIUM|HIGH|CRITICAL)\s*[|:\-]\s*([\s\S]+)$/i);
if (m) { severity = m[1].toUpperCase(); summary = m[2]; }
else if (raw) { summary = raw; }
summary = summary.replace(/\s+/g, ' ').trim();
if (!summary) {
  summary = d.monitoringError
    ? 'Monitoring error: ' + d.errors.join('; ')
    : d.daysRemaining + ' days to expiry; nameservers ' + (d.nsChanged ? 'changed' : 'unchanged') + ' (AI summary unavailable).';
}
if (summary.length > 300) summary = summary.slice(0, 297) + '...';

const verdict = d.monitoringError ? 'ERROR' : (d.alertRequired ? 'ALERT' : 'NO ALERT');
const ist = new Date(Date.now() + 5.5 * 3600 * 1000).toISOString().slice(0, 16).replace('T', ' ');
const executionId = String($execution.id);

return [{ json: {
  executionId,
  timestampIst: ist + ' IST',
  verdict, severity, summary,
  modelOutput: raw || '(no model output)',
  inputSha256: d.input_sha256,
  prevHash: d.prevHash,
  alertRequired: d.alertRequired,
  monitoringError: d.monitoringError,
  sendTelegram: d.alertRequired || d.monitoringError,
  expiryDate: d.expiryDate,
  nameserversJson: JSON.stringify(d.currentNS),
  telegramText: '🟣 NGP-044 | exec #' + executionId + ' | ' + ist + ' IST | ' + verdict + ' / ' + severity + ' | ' + summary
}}];

// Command routing is done by the Switch node; this only identifies which branch ran.
const msg = $('Telegram Trigger').first().json.message || {};
const text = (msg.text || '').trim();
const userId = String(msg.from?.id ?? '');
const chatId = msg.chat?.id;
let command = 'unknown';
if ($('Query Status').isExecuted) command = 'status';
else if ($('Query Last N').isExecuted) command = 'last';
else if (userId !== 'YOUR_TELEGRAM_USER_ID') command = 'unauthorized';
let error = '';
if (command === 'unknown' && /^\/last\b/i.test(text)) {
  const arg = text.split(/\s+/)[1];
  error = arg === undefined
    ? 'Missing number. Use /last N where N is 1-50, e.g. /last 5.'
    : 'Invalid N "' + arg + '". N must be a whole number from 1 to 50.';
}
const p = { command, chatId, userId, text, error };
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const ist = new Date(Date.now() + 5.5 * 3600 * 1000).toISOString().slice(0, 16).replace('T', ' ');
let verdict = 'INFO', severity = 'INFO', summary = '';

if (p.command === 'unauthorized') {
  verdict = 'DENIED'; severity = 'LOW';
  summary = 'You are not authorized to query this watchdog.';
} else if (p.command === 'unknown') {
  verdict = 'ERROR'; severity = 'LOW';
  summary = p.error || 'Unknown command. Use /status or /last N (1-50).';
} else if (p.command === 'status') {
  verdict = 'STATUS';
  if (!rows.length) { severity = 'LOW'; summary = 'No successful check recorded yet.'; }
  else {
    const r = rows[0];
    const exp = new Date(r.expiry_date);
    const now = new Date();
    const days = Math.round((Date.UTC(exp.getUTCFullYear(), exp.getUTCMonth(), exp.getUTCDate()) -
      Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())) / 86400000);
    const ns = typeof r.nameservers_json === 'string' ? JSON.parse(r.nameservers_json) : r.nameservers_json;
    severity = days < 24 ? 'MEDIUM' : 'INFO';
    summary = 'apache.org expires ' + exp.toISOString().slice(0, 10) + ' (' + days + ' days left); NS: ' +
      ns.join(', ') + '; last successful check ' + new Date(new Date(r.checked_at).getTime() + 5.5 * 3600 * 1000).toISOString().slice(0, 16).replace('T', ' ') + ' IST.';
  }
} else if (p.command === 'last') {
  verdict = 'HISTORY';
  if (!rows.length) { severity = 'LOW'; summary = 'No audit records yet.'; }
  else summary = 'Last ' + rows.length + ': ' +
    rows.map(r => r.timestamp_ist + ' ' + r.verdict + '/' + r.severity).join(' ; ');
}
return [{ json: {
  chatId: p.chatId,
  executionId: String($execution.id),
  timestampIst: ist + ' IST',
  command: p.command,
  rawText: p.text || '',
  userId: p.userId,
  verdict, severity, summary,
  text: '🟣 NGP-044 | exec #' + $execution.id + ' | ' + ist + ' IST | ' + verdict + ' / ' + severity + ' | ' + summary
}}];

const r = $('Format Reply').first().json;
const prev = $input.first().json || {};
const prevHash = prev.input_sha256 || 'GENESIS';
// Canonical JSON with fixed key order. Includes prevHash, so each entry chains to the one before it.
const canonical = JSON.stringify({
  tag: 'NGP-044', kind: 'bot_command', executionId: r.executionId,
  timestampIst: r.timestampIst, userId: r.userId, command: r.command,
  rawText: r.rawText, verdict: r.verdict, severity: r.severity,
  summary: r.summary, prevHash
});
return [{ json: {
  executionId: r.executionId, timestampIst: r.timestampIst,
  verdict: r.verdict, severity: r.severity, summary: r.summary,
  modelOutput: 'n/a (bot command: ' + (r.rawText || '(empty)') + ', user ' + r.userId + ')',
  prevHash, canonical
}}];
